def combine_time_offsets(hh, mm, offset1_minutes, offset2_minutes):
    total = hh * 60 + mm + offset1_minutes + offset2_minutes
    day_delta = total // 1440
    rem = total % 1440
    return (rem // 60, rem % 60, day_delta)

def chunk_by_predicate_change(lst):
    if not lst:
        return []
    out = []
    current = [lst[0]]
    prev_even = lst[0] % 2 == 0
    for x in lst[1:]:
        even = x % 2 == 0
        if even == prev_even:
            current.append(x)
        else:
            out.append(current)
            current = [x]
            prev_even = even
    out.append(current)
    return out

def days_until_next_birthday(birth_md, today_ymd):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    def dim_list(y):
        return [31, 29 if is_leap(y) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    def doy(y, m, d):
        return sum(dim_list(y)[:m - 1]) + d
    def days_in_year(y):
        return 366 if is_leap(y) else 365
    m, d = birth_md
    y, tm, td = today_ymd
    today_doy = doy(y, tm, td)
    bday_doy = doy(y, m, d)
    if bday_doy >= today_doy:
        return bday_doy - today_doy
    return (days_in_year(y) - today_doy) + doy(y + 1, m, d)

def title_case_words(s):
    words = s.split()
    return " ".join(w[0].upper() + w[1:].lower() if w else w for w in words)

def count_palindromes_in_range(a, b):
    count = 0
    for x in range(a, b + 1):
        s = str(x)
        if s == s[::-1]:
            count += 1
    return count

def weekend_count_given_start_weekday(start_weekday, num_days):
    count = 0
    for i in range(num_days):
        if (start_weekday + i) % 7 in (5, 6):
            count += 1
    return count

def add_months_to_date(y, m, d, n_months):
    def is_leap(yr):
        return yr % 4 == 0 and (yr % 100 != 0 or yr % 400 == 0)
    total = (y * 12 + (m - 1)) + n_months
    ny = total // 12
    nm = total % 12 + 1
    dim = [31, 29 if is_leap(ny) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][nm - 1]
    nd = min(d, dim)
    return (ny, nm, nd)

def kth_largest_distinct(lst, k):
    distinct = sorted(set(lst), reverse=True)
    if k < 1 or k > len(distinct):
        return None
    return distinct[k - 1]

def wrap_text(text, width):
    words = text.split()
    lines = []
    current = ''
    for w in words:
        if not current:
            current = w
        elif len(current) + 1 + len(w) <= width:
            current += ' ' + w
        else:
            lines.append(current)
            current = w
    if current:
        lines.append(current)
    return lines

def partition_by_threshold(lst, t):
    below = [x for x in lst if x < t]
    at_or_above = [x for x in lst if x >= t]
    return (below, at_or_above)

def rotate_matrix_90(matrix):
    if not matrix:
        return []
    n = len(matrix)
    return [[matrix[n-1-r][c] for r in range(n)] for c in range(n)]

def is_valid_tic_tac_toe_counts(board):
    if len(board) != 3:
        return False
    for row in board:
        if len(row) != 3:
            return False
    x_count = o_count = 0
    for row in board:
        for c in row:
            if c == 'X':
                x_count += 1
            elif c == 'O':
                o_count += 1
            elif c != ' ':
                return False
    return x_count == o_count or x_count == o_count + 1

def count_runs(s):
    if not s:
        return 0
    count = 1
    for i in range(1, len(s)):
        if s[i] != s[i - 1]:
            count += 1
    return count

def is_emirp(n):
    def is_prime(x):
        if x < 2:
            return False
        if x < 4:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True
    rev = int(str(n)[::-1])
    return is_prime(n) and is_prime(rev) and rev != n

def is_semiperfect_number(n):
    if n <= 0:
        return False
    divs = [i for i in range(1, n) if n % i == 0]
    dp = {0}
    for d in divs:
        new = set()
        for s in dp:
            if s + d <= n:
                new.add(s + d)
        dp |= new
    return n in dp

def format_ordinal_date(day, month_name):
    a = abs(day)
    if 11 <= a % 100 <= 13:
        suf = 'th'
    else:
        suf = {1: 'st', 2: 'nd', 3: 'rd'}.get(a % 10, 'th')
    return f"{day}{suf} of {month_name}"

def letter_to_number_sum(s):
    total = 0
    for c in s:
        if c.isalpha():
            total += ord(c.lower()) - ord('a') + 1
    return total

def age_group_counts(ages):
    d = {}
    for a in ages:
        if a >= 100:
            label = "100+"
        else:
            low = (a // 10) * 10
            label = f"{low}-{low + 9}"
        d[label] = d.get(label, 0) + 1
