def camel_case_acronym(s):
    if not s:
        return ""
    result = [s[0].upper()]
    for c in s[1:]:
        if c.isupper():
            result.append(c)
    return "".join(result)

def oxford_join_quoted(items):
    quoted = [f'"{i}"' for i in items]
    if not quoted:
        return ""
    if len(quoted) == 1:
        return quoted[0]
    if len(quoted) == 2:
        return f"{quoted[0]} and {quoted[1]}"
    return ", ".join(quoted[:-1]) + f", and {quoted[-1]}"

def reformat_date_us(date_str):
    y, m, d = date_str.split('-')
    return f'{m}/{d}/{y}'

def longest_words(words):
    maxlen = max(len(w) for w in words)
    return sorted(w for w in words if len(w) == maxlen)

import math
def count_common_divisors(a, b):
    g = math.gcd(a, b)
    count = 0
    i = 1
    while i * i <= g:
        if g % i == 0:
            count += 1 if i * i == g else 2
        i += 1
    return count

def find_max_sum_subarray_of_size_k(lst, k):
    best = cur = sum(lst[:k])
    for i in range(k, len(lst)):
        cur += lst[i] - lst[i - k]
        best = max(best, cur)
    return best

def is_valid_matrix_shape(m, rows, cols):
    if len(m) != rows:
        return False
    return all(len(r) == cols for r in m)
